const $ = (sel, root=document) => root.querySelector(sel);
const app = $('#app');
const state = {me:null,page:'dashboard',csrf:'',data:{},authTab:'login',busy:false,menu:false,feedOffset:0,channel:'general',target:'',commentsFor:null,modal:null};
const roles={FUNDADOR:'Fundador',ADMIN_MEMBROS:'Admin. Membros',ADMIN_OPERACIONAL:'Admin. Operacional',CAPITAO:'Capitão',MEMBRO:'Membro',PENDENTE:'Pendente'};
const adminRoles=['FUNDADOR','ADMIN_MEMBROS','ADMIN_OPERACIONAL'];
const operations=['FUNDADOR','ADMIN_OPERACIONAL'];
const membersAdmin=['FUNDADOR','ADMIN_MEMBROS'];
const leaders=[...adminRoles,'CAPITAO'];
const paths={
 dashboard:'<rect x="3" y="3" width="7" height="9" rx="1"/><rect x="14" y="3" width="7" height="5" rx="1"/><rect x="14" y="12" width="7" height="9" rx="1"/><rect x="3" y="16" width="7" height="5" rx="1"/>',
 users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
 shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',
 swords:'<path d="m14.5 17.5 3-3L6 3 3 6l11.5 11.5ZM13 19l6-6M16 16l4 4M19 21l2-2M9.5 17.5l-3-3L18 3l3 3L9.5 17.5ZM11 19l-6-6M8 16l-4 4M5 21l-2-2"/>',
 trophy:'<path d="M8 21h8m-4-4v4M7 4h10v7a5 5 0 0 1-10 0V4ZM7 6H4a2 2 0 0 0 0 4h3M17 6h3a2 2 0 0 1 0 4h-3"/>',
 radio:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M3 11h18M7 3h10M7 16h4"/>',
 message:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',
 bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4"/>',
 settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2 2-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6V21h-3v-.2a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1-2-2 .1-.1a1.7 1.7 0 0 0 .3-1.9 1.7 1.7 0 0 0-1.6-1H5v-3h.2a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9l-.1-.1 2-2 .1.1a1.7 1.7 0 0 0 1.9.3 1.7 1.7 0 0 0 1-1.6V5h3v.2a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1 2 2-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v3h-.2a1.7 1.7 0 0 0-1.6 1Z"/>',
 command:'<path d="m5 5 14 14M19 5 5 19M12 2v20M2 12h20"/>',
 file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',
 logout:'<path d="M10 17l5-5-5-5M15 12H3M12 3h6a3 3 0 0 1 3 3v12a3 3 0 0 1-3 3h-6"/>',
 chevron:'<path d="m9 18 6-6-6-6"/>',
 menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',
 heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 1 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',
 crown:'<path d="m2 7 5 5 5-8 5 8 5-5-2 13H4L2 7Z"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 refresh:'<path d="M3 11a9 9 0 1 1 3 7M3 4v7h7"/>',
 pin:'<path d="m16 3 5 5-4 1-3 5-3 7-1-8-5-5 5-3 1-4 5 2Z"/>',
 check:'<path d="m4 12 5 5L20 6"/>',
 alert:'<path d="M12 3 2 21h20L12 3Z"/><path d="M12 9v5m0 3h.01"/>',
 lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
 info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',
 edit:'<path d="m3 17 12-12 4 4L7 21H3v-4ZM14 6l4 4"/>',
 eye:'<path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6-10-6-10-6Z"/><circle cx="12" cy="12" r="3"/>'
};
function ico(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.shield}</svg>`;}
function esc(s){return String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function eattr(s){return esc(s);}
function initials(name){return esc((name||'?').slice(0,2).toUpperCase());}
function date(s){if(!s)return '—';try{return new Intl.DateTimeFormat('pt-PT',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Lisbon'}).format(new Date(s));}catch{return esc(s);}}
function tag(text,type='dim'){return `<span class="tag ${type}">${esc(text)}</span>`;}
function roleTag(role){return tag(roles[role]||role,role==='FUNDADOR'?'red':role==='MEMBRO'?'good':'dim');}
function avatar(name,cls=''){return `<span class="avatar ${cls}">${initials(name)}</span>`;}
function empty(title,description,icon='info'){return `<div class="empty">${ico(icon)}<strong>${esc(title)}</strong>${esc(description||'')}</div>`;}
function field(name,label,placeholder='',type='text',value='',required=true){return `<div class="field"><label for="f-${esc(name)}">${esc(label)}</label><input id="f-${esc(name)}" name="${esc(name)}" placeholder="${esc(placeholder)}" type="${esc(type)}" value="${eattr(value)}" ${required?'required':''} /></div>`;}
function btn(text,kind='secondary',iconName='',extra=''){return `<button class="btn ${kind}" ${extra}>${iconName?ico(iconName):''}${esc(text)}</button>`;}
function blockHeader(title,right=''){return `<div class="card-header"><h2 class="section-title">${esc(title)}</h2>${right}</div>`;}
const navGroups=[
 {title:'CENTRO DE COMANDO',links:[['dashboard','Painel geral','dashboard']]},
 {title:'A MATILHA',links:[['members','Membros','users'],['teams','Equipas & reserva','shield'],['feed','Feed da guilda','radio'],['messages','Comunicações','message'],['hall','Hall de honra','trophy']]},
 {title:'OPERAÇÕES',links:[['wars','Guerras','swords'],['ranking','Ranking semanal','trophy'],['events','Agenda & eventos','calendar']]},
 {title:'SISTEMA',links:[['notifications','Notificações','bell'],['profile','O meu perfil','settings'],['admin','Administração','command'],['intelligence','Inteligência operacional','eye'],['proposals','Dupla aprovação','crown']]}
];
const titles={dashboard:'Centro de comando',members:'Membros',teams:'Equipas & reserva',feed:'Feed da matilha',messages:'Comunicações',wars:'Guerras de guilda',ranking:'Ranking semanal',events:'Agenda & eventos',hall:'Hall de honra',intelligence:'Inteligência operacional',notifications:'Notificações',profile:'O meu perfil',admin:'Administração',proposals:'Conselho dos fundadores'};
function hasAny(list){return list.includes(state.me?.role);}
function allowed(page){if(page==='admin')return hasAny(adminRoles);if(page==='proposals')return hasAny(['FUNDADOR']);if(page==='intelligence')return hasAny(operations);return titles[page]!==undefined;}
function sidebar(){return `<aside class="sidebar ${state.menu?'open':''}" id="sidebar">
 <div class="brand"><span class="brand-symbol">FB</span><span><div class="brand-name">FENRIRBLOOD</div><div class="brand-sub">MYTHIC WOLF // EU</div></span></div>
 <nav aria-label="Navegação principal">${navGroups.map(g=>{const links=g.links.filter(([p])=>allowed(p));return links.length?`<div class="nav-group">${g.title}</div>${links.map(([p,label,icon])=>`<button class="nav-button ${state.page===p?'active':''}" data-nav="${p}" ${state.page===p?'aria-current="page"':''}>${ico(icon)}<span>${label}</span></button>`).join('')}`:'';}).join('')}</nav>
 <div class="nav-footer"><div class="user-chip">${avatar(state.me.username)}<span class="grow" style="min-width:0"><div class="name">${esc(state.me.username)}</div><div class="rank">${esc(roles[state.me.role])}</div></span></div><button class="nav-button" data-action="logout">${ico('logout')} Terminar sessão</button></div>
 </aside>`;}
function shell(){const shortcut=['dashboard','teams','wars','feed','messages'];return `<div class="shell"><div class="mobile-overlay ${state.menu?'open':''}" data-action="menu-close"></div>${sidebar()}
 <div class="main-area"><header class="topbar"><div class="row"><button class="icon-btn mobile-menu-btn" aria-label="Abrir menu" data-action="menu-toggle">${ico('menu')}</button><div class="topbar-path"><span>FENRIRBLOOD</span><span class="slash">/</span><strong>${esc(titles[state.page]||'Painel')}</strong></div></div><div class="top-right"><span class="server-mark"><span class="pulse"></span>&nbsp; EU SERVER</span><button class="icon-btn" data-nav="notifications" aria-label="Ver notificações">${ico('bell')}${state.data.unread?'<i class="notification-dot"></i>':''}</button>${avatar(state.me.username,'sm')}</div></header>
 <main id="content" class="content" aria-live="polite"></main></div>
 <nav class="mobile-tabbar" aria-label="Acesso rápido">${shortcut.map(p=>`<button class="mobile-tab ${state.page===p?'active':''}" data-nav="${p}">${ico(({dashboard:'dashboard',teams:'shield',wars:'swords',feed:'radio',messages:'message'})[p])}<span>${p==='dashboard'?'Início':p==='teams'?'Equipas':p==='wars'?'Guerras':p==='feed'?'Feed':'Chat'}</span></button>`).join('')}</nav></div>`;}
function heading(kicker,title,sub,action=''){return `<section class="page-heading"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${esc(sub||'')}</p></div>${action}</section>`;}
async function api(path,method='GET',body){const headers={'Accept':'application/json'};if(method!=='GET'){headers['Content-Type']='application/json';if(state.csrf)headers['X-CSRF-Token']=state.csrf;}let r;
 try{r=await fetch(path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin',cache:'no-store'});}catch{throw Error('Falha de ligação. Verifica a internet e tenta novamente.');}
 let data;try{data=await r.json();}catch{data={detail:'Resposta inválida do servidor'};}
 if(!r.ok){if(r.status===401&&state.me){state.me=null;renderAuth();}throw Error(typeof data.detail==='string'?data.detail:'O servidor não conseguiu concluir a operação.');}
 return data;}
let toastTimer;
function flash(message,ok=false){const t=$('#toast');t.innerHTML=`<div class="toast-msg ${ok?'ok':''}"></div>`;t.firstElementChild.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.innerHTML='',4600);}
function formObj(form){const data={};for(const [k,v] of new FormData(form).entries())data[k]=String(v);return data;}
function escapeRoleNotice(){return `<div class="warning">As ações sensíveis são verificadas no servidor, independentemente do que aparece nesta interface.</div>`;}

// AUTH / ACCOUNT STATES
function renderAuth(){state.me=null;state.menu=false;const register=state.authTab==='register';const recovery=state.authTab==='recover';const reset=new URLSearchParams(location.search).get('reset');app.innerHTML=`<div class="auth-layout"><div class="auth-art"><div class="auth-visual"><div class="auth-logo"><span>FB</span></div><div class="auth-name">FENRIRBLOOD</div><div class="auth-slogan">A MATILHA NÃO SE CURVA.</div></div><div class="auth-art-footer"><span>FREE FIRE // SERVIDOR EUROPA</span><span>EST. 2026 — MYTHIC WOLF</span></div></div><div class="auth-side"><div class="auth-form-wrap"><div class="eyebrow">ACESSO RESTRITO // FENRIR SYSTEM</div><h1 class="auth-heading">${reset?'Redefinir acesso':recovery?'Recuperar conta':register?'Junta-te à matilha':'Identifica-te, guerreiro.'}</h1><p class="auth-copy">${reset?'Escolhe uma nova palavra-passe segura.':recovery?'A recuperação por email depende da configuração do servidor.':register?'O teu pedido ficará pendente até aprovação administrativa.':'O centro de comando só está disponível para membros autorizados.'}</p>
 ${reset?`<form data-form="reset" class="form-fields">${field('password','Nova palavra-passe (mín. 12 caracteres)','','password')}<button class="btn primary wide">Atualizar palavra-passe ${ico('arrow')}</button></form>`:recovery?`<form data-form="recover" class="form-fields">${field('email','Email da conta','jogador@email.pt','email')}<button class="btn primary wide">Pedir recuperação ${ico('arrow')}</button></form><button class="btn ghost wide" style="margin-top:14px" data-action="auth-login">Voltar ao login</button>`:`<div class="auth-tabs"><button class="auth-tab ${!register?'active':''}" data-action="auth-login">Iniciar sessão</button><button class="auth-tab ${register?'active':''}" data-action="auth-register">Criar conta</button></div><form data-form="${register?'register':'login'}" class="form-fields">${register?field('username','Nome de jogador','O teu nome na guilda'):''}${field('email','Endereço de email','nome@email.pt','email')}${register?field('ff_uid','UID Free Fire (opcional)','O teu UID','text','',false):''}${field('password',register?'Palavra-passe (mín. 12 caracteres)':'Palavra-passe','••••••••••••','password')}<button class="btn primary wide" type="submit">${register?'Enviar candidatura':'Entrar no centro de comando'} ${ico('arrow')}</button></form>${!register?`<button class="btn ghost wide" style="margin-top:13px" data-action="auth-recover">Esqueceste-te da palavra-passe?</button>`:''}`}
 <div class="auth-footer">SESSÃO SEGURA · ACESSO POR APROVAÇÃO · EUROPA</div></div></div></div>`;}
function accountScreen(){const suspended=state.me.status==='SUSPENDED';app.innerHTML=`<div class="auth-layout"><div class="auth-art"><div class="auth-visual"><div class="auth-logo"><span>FB</span></div><div class="auth-name">FENRIRBLOOD</div><div class="auth-slogan">A MATILHA NÃO SE CURVA.</div></div></div><div class="auth-side"><div class="auth-form-wrap"><div class="eyebrow">ESTADO DA TUA CONTA</div><h1 class="auth-heading">${suspended?'Acesso suspenso':'Candidatura em análise'}</h1><p class="auth-copy">${suspended?'A tua conta encontra-se temporariamente suspensa. Podes apresentar um recurso, sujeito a análise.':'Olá, '+esc(state.me.username)+'. O teu registo foi recebido. Aguarda que um administrador aprove a tua entrada na guilda.'}</p>${suspended?`<form data-form="appeal" class="form-fields"><div><label for="appeal">Justificação do recurso</label><textarea id="appeal" name="reason" required minlength="5" maxlength="1000" placeholder="Explica o motivo do teu recurso..."></textarea></div><button class="btn primary wide">Enviar recurso</button></form>`:`<div class="pending-notice">${ico('clock')} O teu acesso será desbloqueado após aprovação.</div>`}<div class="row wrap" style="margin-top:20px"><button class="btn secondary" data-action="check-account">Verificar estado</button><button class="btn ghost" data-action="logout">Terminar sessão</button></div></div></div></div>`;}
async function init(){const hash=location.hash.replace('#','');if(titles[hash])state.page=hash;try{const me=await api('/api/auth/me');state.me=me;state.csrf=me.csrf;if(me.status!=='ACTIVE')accountScreen();else await showPage();}catch{renderAuth();}}
async function showPage(){if(!state.me)return renderAuth();if(state.me.status!=='ACTIVE')return accountScreen();if(!allowed(state.page))state.page='dashboard';state.menu=false;app.innerHTML=shell();const content=$('#content');content.innerHTML='<div class="empty">A carregar os dados da matilha…</div>';try{let output=await renderPage(state.page);const dest=$('#content');if(dest&&state.me&&state.me.status==='ACTIVE')dest.innerHTML=output;}catch(e){const dest=$('#content');if(dest)dest.innerHTML=`${heading('ERRO','Não foi possível carregar','Verifica a ligação e volta a tentar.')}<div class="warning">${esc(e.message)}</div><div style="margin-top:16px">${btn('Recarregar','secondary','refresh','data-action="reload"')}</div>`;}}
async function renderPage(page){switch(page){case'dashboard':return dashboard();case'members':return members();case'teams':return teams();case'wars':return wars();case'ranking':return ranking();case'feed':return feed();case'messages':return messages();case'events':return events();case'notifications':return notifications();case'hall':return hall();case'intelligence':return intelligence();case'profile':return profile();case'admin':return admin();case'proposals':return proposals();default:return dashboard();}}

async function dashboard(){const d=await api('/api/dashboard');state.data.dashboard=d;const st=d.members||{};const stat=(label,value,icon,extra)=>`<div class="card stat-card"><div class="row between"><div class="stat-icon">${ico(icon)}</div>${tag(extra,'dim')}</div><div style="margin-top:18px" class="metric-value">${Number(value)||0}</div><div class="metric-label">${esc(label)}</div></div>`;
 return `${heading('COMANDO CENTRAL // EUROPE','Bem-vindo à Matilha, '+state.me.username,'Informação operacional sincronizada com a base de dados.',btn('Ver equipas','secondary','arrow','data-nav="teams"'))}
 <div class="hero"><div class="hero-inner"><div class="eyebrow">FENRIRBLOOD // MYTHIC WOLF</div><h1>A MATILHA<br><span>NÃO SE CURVA.</span></h1><p>Força coletiva. Disciplina. Estratégia. O centro de comando da guilda Free Fire — Servidor Europa.</p><div class="hero-actions">${btn('Operações de guerra','primary','swords','data-nav="wars"')}${btn('Membros da guilda','secondary','users','data-nav="members"')}</div></div></div>
 <div class="grid cols-4" style="margin-bottom:24px">${stat('Membros registados',st.total,'users','TOTAL')}${stat('Membros ativos',st.active,'shield','ATIVOS')}${stat('Online agora',st.online,'radio','5 MIN')}${stat('Equipas incompletas',d.teams?.incomplete,'alert','SQUADS')}</div>
 <div class="grid cols-2" style="margin-bottom:22px"><div class="card">${blockHeader('Próximas guerras',btn('Ver todas','ghost','arrow','data-nav="wars"'))}${d.wars.length?`<div class="line-list">${d.wars.map(w=>`<div class="line-item"><div><div class="line-title">${esc(w.title)}</div><div class="line-sub">vs. ${esc(w.opponent)} · ${date(w.starts_at)}</div></div>${tag(w.status,'red')}</div>`).join('')}</div>`:empty('Nenhuma guerra agendada','As próximas guerras aparecerão aqui após serem registadas.','swords')}</div>
 <div class="card">${blockHeader('Ranking desta semana',btn('Ranking completo','ghost','arrow','data-nav="ranking"'))}${d.ranking.length?renderMiniRanking(d.ranking):empty('Ranking ainda vazio','Os pontos serão apresentados após o primeiro registo.','trophy')}</div></div>
 <div class="grid cols-2"><div class="card">${blockHeader('Agenda operacional',btn('Agenda','ghost','calendar','data-nav="events"'))}${d.events.length?d.events.map(ev=>`<div class="line-item"><div><div class="line-title">${esc(ev.title)}</div><div class="line-sub">${date(ev.starts_at)}</div></div>${ico('chevron')}</div>`).join(''):empty('Sem eventos próximos','Cria um evento para que a equipa saiba o que vem a seguir.','calendar')}</div>
 <div class="card">${blockHeader(hasAny(adminRoles)?'Registo de atividade':'Acesso rápido')}${hasAny(adminRoles)?(d.activity.length?d.activity.map(a=>`<div class="line-item"><div><div class="line-title">${esc(a.action.replaceAll('_',' '))}</div><div class="line-sub">${esc(a.username||'Sistema')} · ${date(a.created_at)}</div></div></div>`).join(''):empty('Sem atividade registada','As ações da guilda aparecerão aqui.')):`<div class="stack">${[['Feed da guilda','feed','radio'],['Comunicações','messages','message'],['Diretório de membros','members','users']].map(([text,p,icon])=>`<button class="nav-button" data-nav="${p}">${ico(icon)} ${text} ${ico('chevron')}</button>`).join('')}</div>`}</div></div>`;}
function renderMiniRanking(data){const max=Math.max(1,...data.map(x=>Number(x.points)||0));return `<div class="stack" style="gap:16px">${data.map((x,i)=>`<div class="rank-details"><div class="rank-row"><span class="rank-num">${String(i+1).padStart(2,'0')}</span><span class="rank-name">${esc(x.username)}</span><span class="rank-points">${Number(x.points)} PT</span></div><div class="meter-track"><div class="meter-fill" style="width:${Math.max(0,Math.min(100,Number(x.points)/max*100))}%"></div></div></div>`).join('')}</div>`;}

async function members(){const result=await api('/api/members');state.data.members=result.members;return `${heading('EFETIVO DA MATILHA','Diretório de membros','Jogadores, cargos e presença da FENRIRBLOOD.',`<div class="member-search"><input type="search" id="member-filter" placeholder="Pesquisar jogador / UID…" aria-label="Pesquisar membros"></div>`)}<div id="member-list">${memberCards(result.members)}</div>`;}
function memberCards(users){if(!users.length)return empty('Nenhum membro encontrado','Os membros aprovados aparecerão aqui.','users');return `<div class="member-grid">${users.map(u=>`<article class="member-card"><div class="user-line">${avatar(u.username)}<div style="min-width:0"><strong class="ellipsis" style="display:block">${esc(u.username)}</strong><small>UID: ${esc(u.ff_uid||'Não indicado')}</small></div></div><p class="caption" style="min-height:24px">${esc((u.bio||'Sem descrição').slice(0,95))}</p><div class="foot">${roleTag(u.role)}<button class="btn ghost tiny" data-action="view-member" data-id="${u.id}">Ver perfil</button></div></article>`).join('')}</div>`;}

async function teams(){const d=await api('/api/teams');state.data.teams=d;const canCreate=hasAny(operations);const canManage=hasAny([...operations,'CAPITAO']);const allCandidates=canCreate?(await api('/api/members')).members.filter(m=>m.status==='ACTIVE'):d.reserve;return `${heading('ORGANIZAÇÃO TÁTICA','Equipas & reserva geral','Esquadrões fixos de quatro jogadores e mobilidade controlada.',canCreate?btn('Criar esquadrão','primary','plus','data-action="create-team"'):'')}
 <div class="grid cols-3">${d.teams.length?d.teams.map(t=>`<article class="card team-panel"><div class="row between"><div><span class="tiny-kicker">ESQUADRÃO // ${esc(t.id.slice(0,5).toUpperCase())}</span><div class="team-name" style="margin-top:8px">${esc(t.name)}</div></div>${tag(t.members.length===4?'COMPLETO':'EM FORMAÇÃO',t.members.length===4?'good':'warn')}</div><div class="slots">${[0,1,2,3].map(i=>`<div class="slot ${t.members[i]?'':'empty-slot'}">${t.members[i]?initials(t.members[i].username):'+'}</div>`).join('')}<div class="grow"></div><span class="slot-count">${t.members.length}/4</span></div><div class="line-sub">Capitão: ${esc(t.captain_name||'Não atribuído')} · Adaptação até ${date(t.adaptation_end_at)}</div><div class="divider"></div>${t.members.length?t.members.map(m=>`<div class="line-item"><div class="profile-title">${avatar(m.username,'sm')}<span><strong>${esc(m.username)}</strong><small>${esc(roles[m.role])}</small></span></div>${canManage?`<button class="btn ghost tiny" data-action="remove-team-member" data-team="${t.id}" data-user="${m.user_id}" aria-label="Remover ${esc(m.username)}">Remover</button>`:''}</div>`).join(''):empty('Equipa vazia','Atribui jogadores a este esquadrão.','shield')}
 ${canManage?`<div class="forms-inset"><form class="inline-form" data-form="team-add"><input type="hidden" name="team_id" value="${t.id}"><div><label>Adicionar / transferir membro</label><select name="user_id" required><option value="">Seleciona um membro</option>${allCandidates.filter(r=>!t.members.some(m=>m.user_id===r.id)).map(r=>`<option value="${r.id}">${esc(r.username)}${d.reserve.some(x=>x.id===r.id)?' · Reserva':' · Transferência'}</option>`).join('')}</select></div><button class="btn primary tiny" type="submit">Adicionar</button></form>${hasAny(operations)&&t.members.length?`<form data-form="team-captain" class="inline-form" style="margin-top:12px"><input type="hidden" name="team_id" value="${t.id}"><div><label>Designar capitão</label><select name="user_id" required>${t.members.map(m=>`<option value="${m.user_id}">${esc(m.username)}</option>`).join('')}</select></div><button class="btn secondary tiny" type="submit">Nomear</button></form>`:''}${hasAny(operations)&&!t.extension_used?`<button class="btn ghost tiny" style="margin-top:10px" data-action="extend-team" data-team="${t.id}">+7 dias de adaptação</button>`:''}</div>`:''}</article>`).join(''):empty('Nenhuma equipa criada','Os esquadrões aparecerão aqui após a criação.','shield')}</div>
 <div class="card" style="margin-top:23px">${blockHeader(`Reserva geral · ${d.reserve.length} jogadores`)}${d.reserve.length?`<div class="member-grid">${d.reserve.map(r=>`<div class="line-item"><div class="profile-title">${avatar(r.username,'sm')}<span><strong>${esc(r.username)}</strong><small>${esc(roles[r.role])}</small></span></div></div>`).join('')}</div>`:empty('Reserva vazia','Todos os membros ativos estão atribuídos a equipas.','users')}</div>`;}

async function wars(){const d=await api('/api/wars');state.data.wars=d.wars;const can=hasAny(operations);return `${heading('TEATRO DE OPERAÇÕES','Guerras de guilda','Planeamento, escalações e resultados registados manualmente.',can?btn('Agendar guerra','primary','plus','data-action="create-war"'):'')}
 <div class="grid cols-2">${d.wars.length?d.wars.map(w=>`<article class="card"><div class="row between"><span class="eyebrow">GUERRA // ${esc(w.id.slice(0,6).toUpperCase())}</span>${tag(w.status,w.status==='DONE'?'good':w.status==='CANCELLED'?'dim':'red')}</div><h2 style="font:700 24px Georgia,serif;margin:16px 0 8px">${esc(w.title)}</h2><div class="muted" style="font-size:12px">FENRIRBLOOD <span style="color:#bf626d">VS.</span> ${esc(w.opponent)}</div><div class="divider"></div><div class="row wrap"><span class="caption">${ico('calendar')} ${date(w.starts_at)}</span>${w.result?tag(w.result,'good'):''}</div>${w.notes?`<p class="caption" style="margin-top:12px">${esc(w.notes)}</p>`:''}<div class="row wrap" style="margin-top:16px">${btn('Ver escalação','secondary','users',`data-action="war-lineup" data-id="${w.id}"`)}${can?btn('Atualizar resultado','ghost','edit',`data-action="war-update" data-id="${w.id}"`):''}</div></article>`).join(''):empty('Nenhuma guerra agendada','Uma guerra só aparecerá aqui quando for criada por um responsável autorizado.','swords')}</div>`;}

async function ranking(){const r=await api('/api/ranking');state.data.ranking=r;const can=hasAny(operations);return `${heading('DESEMPENHO COMPETITIVO','Ranking semanal','Ciclo oficial em Europe/Lisbon · Semana de '+r.week_start,can?btn('Registar pontuação','primary','plus','data-action="add-score"'):'')}
 <div class="grid cols-2"><div class="card">${blockHeader('Classificação individual')}${r.ranking.length?renderMiniRanking(r.ranking):empty('Sem pontuações','Nenhuma pontuação foi registada nesta semana.','trophy')}</div><div class="card">${blockHeader('Regras do ciclo')}${[['Segunda-feira · 00:00','Início do ciclo'],['Segunda-feira · 12:00','Relatório da semana anterior'],['Segunda-feira · 18:00','Fim das correções'],['Segunda-feira · 23:59','Validação final pelos fundadores']].map(([day,desc])=>`<div class="line-item"><div class="line-title">${day}</div><div class="line-sub">${desc}</div></div>`).join('')}<div class="pending-notice">Referência de participação: três dias por semana. Sem mínimo individual obrigatório.</div></div></div>`;}

async function feed(){const r=await api('/api/feed?offset='+state.feedOffset);state.data.feed=r;return `${heading('COMUNIDADE','Feed da matilha','Partilha conquistas, estratégias e novidades com a guilda.')}
 <div style="max-width:790px" class="stack"><div class="card feed-compose">${blockHeader('Nova publicação')}<form data-form="post"><textarea name="body" maxlength="3000" required placeholder="O que queres partilhar com a Matilha?"></textarea><div class="field" style="margin-bottom:12px"><label for="post-images">Imagens (até 4 · máximo 5 MB cada)</label><input type="file" name="images" id="post-images" accept="image/jpeg,image/png,image/webp" multiple></div><div class="row between wrap"><span class="caption">Publicações visíveis aos membros aprovados</span>${btn('Publicar','primary','arrow','type="submit"')}</div></form></div>
 ${r.posts.length?r.posts.map(p=>`<article class="card post-card"><div class="post-top">${avatar(p.author)}<div class="grow"><strong style="font-size:13px">${esc(p.author)}</strong><div class="caption">${date(p.created_at)} ${p.updated_at?'· editado':''}</div></div>${p.pinned?tag('FIXADA','red'):''}${p.author_id===state.me.id||hasAny(adminRoles)?`<button class="btn ghost tiny" data-action="delete-post" data-id="${p.id}">Eliminar</button>`:''}</div><div class="post-body">${esc(p.body)}</div>${p.images?.length?`<div class="post-gallery ${p.images.length>1?'multi':''}">${p.images.map(src=>`<img src="${eattr(src)}" alt="Imagem da publicação de ${esc(p.author)}" loading="lazy">`).join('')}</div>`:''}<div class="post-actions"><button class="mini-icon ${p.liked?'liked':''}" data-action="like-post" data-id="${p.id}">${ico('heart')} ${p.likes} reações</button><button class="mini-icon" data-action="comments" data-id="${p.id}">${ico('message')} ${p.comments} comentários</button></div>${state.commentsFor===p.id?`<section id="comments-${p.id}" class="comments"><div class="caption">A carregar comentários…</div></section><form class="inline-form" data-form="comment" style="margin-top:12px"><input type="hidden" name="post_id" value="${p.id}"><div><input name="body" required maxlength="3000" placeholder="Escrever comentário…" aria-label="Escrever comentário"></div><button class="btn primary tiny">Enviar</button></form>`:''}</article>`).join(''):empty('Ainda sem publicações','A primeira publicação pode ser tua!','radio')}<div class="row wrap">${state.feedOffset>0?btn('Página anterior','secondary','arrow','data-action="feed-prev"'):''}${r.has_more?btn('Página seguinte','secondary','arrow','data-action="feed-more"'):''}</div></div>`;}

async function messages(){let choices=[],caption='Chat geral';if(state.channel==='team'){const ts=(await api('/api/teams')).teams;choices=ts.map(x=>({id:x.id,name:x.name}));}if(state.channel==='war'){const ws=(await api('/api/wars')).wars;choices=ws.map(x=>({id:x.id,name:x.title}));}if(state.channel==='private'){const ms=(await api('/api/members')).members;choices=ms.filter(x=>x.id!==state.me.id&&x.status==='ACTIVE').map(x=>({id:x.id,name:x.username}));}
 if(!choices.length&&state.channel!=='general'&&state.channel!=='admin')state.target='';else if(choices.length&&!choices.some(c=>c.id===state.target))state.target=choices[0].id;
 const channels=['general','team','war','private',...(hasAny(adminRoles)?['admin']:[])];let error=null;let data={messages:[]};if((state.channel==='general'||state.channel==='admin'||state.target)){try{data=await api('/api/messages?channel='+encodeURIComponent(state.channel)+'&target_id='+encodeURIComponent(state.target));}catch(e){error=e.message;}}
 const channelNames={general:'Geral',team:'Equipa',war:'Guerra',private:'Privadas',admin:'Administração'};return `${heading('COMUNICAÇÕES SEGURAS','Centro de mensagens','Mensagens persistentes. O acesso aos canais é validado no servidor.')}
 <div class="card" style="max-width:900px">${blockHeader('Canal ativo',`<span class="tag dim">${esc(channelNames[state.channel])}</span>`)}<div class="channel-row">${channels.map(ch=>`<button class="channel ${ch===state.channel?'active':''}" data-action="channel" data-channel="${ch}">${channelNames[ch]}</button>`).join('')}</div>${choices.length?`<div class="field" style="margin-bottom:16px"><label for="channel-target">${state.channel==='private'?'Conversar com membro':'Selecionar canal'}</label><select id="channel-target">${choices.map(c=>`<option value="${c.id}" ${c.id===state.target?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>`:''}
 ${error?`<div class="warning">${esc(error)}</div>`:!choices.length&&['team','war','private'].includes(state.channel)?empty('Sem canais disponíveis','Ainda não tens acesso a este tipo de canal.','lock'):`<div class="chat-window" id="chat-window">${data.messages.length?data.messages.map(m=>`<div class="bubble ${m.author_id===state.me.id?'mine':''}"><small>${esc(m.author)} · ${date(m.created_at)}</small>${esc(m.body)}</div>`).join(''):empty('Ainda sem mensagens','Inicia uma conversa com a Matilha.','message')}</div><form data-form="message" class="inline-form chat-form"><div><input required maxlength="3000" name="body" autocomplete="off" placeholder="Escrever mensagem para ${esc(channelNames[state.channel])}…" aria-label="Mensagem"></div><button class="btn primary" type="submit">${ico('arrow')} Enviar</button></form>`}</div>`;}

