async function intelligence(){const r=await api('/api/intelligence');return `${heading('CENTRO DE ANÁLISE','Inteligência operacional','Indicadores reais para apoiar, não substituir, decisões humanas.')}
 <div class="warning">${ico('info')} Integração externa de IA indisponível: ${esc(r.ai_reason)} Os indicadores abaixo são calculados por regras verificáveis e dados reais.</div>
 <div class="grid cols-3" style="margin:20px 0">${[['Equipas incompletas',r.incomplete_teams.length,'shield'],['Reserva geral',r.reserve_members.length,'users'],['Guerras agendadas',r.planned_wars,'swords']].map(([title,num,icon])=>`<div class="card">${ico(icon)}<div class="metric-value" style="margin-top:13px">${Number(num)||0}</div><div class="metric-label">${esc(title)}</div></div>`).join('')}</div>
 <div class="grid cols-2"><div class="card">${blockHeader('Alertas operacionais')}${r.rules_based_insights.length?r.rules_based_insights.map(x=>`<div class="line-item"><div><div class="line-title">${esc(x.title)}</div><div class="line-sub">${esc(x.detail)}</div></div>${tag(x.severity,'warn')}</div>`).join(''):empty('Sem alertas detetados','Não foram encontradas situações que correspondam às regras atuais.','check')}</div>
 <div class="card">${blockHeader('Análise de atividade humana')}<div class="line-list">${r.inactive_members.length?r.inactive_members.map(x=>`<div class="line-item"><span class="line-title">${esc(x.username)}</span><span class="caption">${x.last_seen?date(x.last_seen):'Nunca online'}</span></div>`).join(''):empty('Sem membros a sinalizar','Nenhuma ausência superior a sete dias foi identificada.','users')}</div><div class="pending-notice">A ausência é um indicador para revisão, não uma infração automática.</div></div></div>`;}

function modal(title,content){state.modal=true;document.body.insertAdjacentHTML('beforeend',`<div class="modal-shade" id="modal-shade" role="presentation"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="row between" style="margin-bottom:14px"><h2>${esc(title)}</h2><button class="btn ghost tiny" data-action="modal-close">Fechar ×</button></div>${content}</section></div>`);}
function closeModal(){state.modal=false;$('#modal-shade')?.remove();}
function formTemplate(fields,kind,submit='Guardar'){return `<form data-form="${kind}" class="form-fields">${fields}${btn(submit,'primary','check','type="submit"')}</form>`;}
function optionMembers(items){return `<option value="">Seleciona um jogador…</option>${items.map(x=>`<option value="${x.id}">${esc(x.username)}</option>`).join('')}`;}

async function go(page){if(!allowed(page))return;closeModal();state.page=page;state.menu=false;state.feedOffset=0;if(page!=='feed')state.commentsFor=null;location.hash=page;window.scrollTo({top:0,behavior:'instant'});await showPage();if(page==='feed'&&state.commentsFor)await loadComments(state.commentsFor);if(page==='messages'){$('#chat-window')?.scrollTo(0,$('#chat-window').scrollHeight);}}
async function refresh(){await showPage();if(state.page==='feed'&&state.commentsFor)await loadComments(state.commentsFor);if(state.page==='messages'){$('#chat-window')?.scrollTo(0,$('#chat-window').scrollHeight);}}
async function loadComments(id){const container=$('#comments-'+id);if(!container)return;try{const data=await api(`/api/feed/${encodeURIComponent(id)}/comments`);container.innerHTML=data.comments.length?data.comments.map(c=>`<div class="comment"><span class="name">${esc(c.author)}</span>${esc(c.body)}</div>`).join(''):'<span class="caption">Ainda não existem comentários.</span>';}catch(e){container.textContent=e.message;}}
async function actionClick(el){const action=el.dataset.action;const id=el.dataset.id;switch(action){
 case'menu-toggle':state.menu=!state.menu;$('#sidebar')?.classList.toggle('open',state.menu);$('.mobile-overlay')?.classList.toggle('open',state.menu);break;
 case'menu-close':state.menu=false;$('#sidebar')?.classList.remove('open');$('.mobile-overlay')?.classList.remove('open');break;
 case'auth-login':state.authTab='login';renderAuth();break;
 case'auth-register':state.authTab='register';renderAuth();break;
 case'auth-recover':state.authTab='recover';renderAuth();break;
 case'check-account':{const r=await api('/api/auth/me');state.me=r;state.csrf=r.csrf;if(r.status==='ACTIVE')await go('dashboard');else{accountScreen();flash('A candidatura continua pendente.');}break;}
 case'logout':await api('/api/auth/logout','POST');state.me=null;state.csrf='';state.authTab='login';renderAuth();break;
 case'logout-all':if(confirm('Queres terminar todas as sessões, incluindo esta?')){await api('/api/auth/logout-all','POST');state.me=null;state.csrf='';renderAuth();flash('Sessões terminadas.',true);}break;
 case'view-member':{const u=await api(`/api/members/${id}`);modal('Ficha do jogador',`<div class="row" style="margin-bottom:20px">${avatar(u.username,'lg')}<div><h2>${esc(u.username)}</h2>${roleTag(u.role)}</div></div><div class="stack"><div class="line-item"><span>UID Free Fire</span><strong>${esc(u.ff_uid||'Não indicado')}</strong></div><div class="line-item"><span>Equipa</span><strong>${esc(u.team?.name||'Reserva geral')}</strong></div><div class="line-item"><span>Pontos esta semana</span><strong>${Number(u.weekly_points)||0}</strong></div><div class="line-item"><span>Guerras confirmadas</span><strong>${Number(u.war_confirmations)||0}</strong></div><p class="caption">${esc(u.bio||'Sem apresentação adicionada.')}</p><div><h3>Conquistas</h3>${u.awards.length?u.awards.map(a=>`<div class="line-item">${esc(a.title)}</div>`).join(''):empty('Sem conquistas','Ainda não foram atribuídas medalhas.')}</div></div>`);break;}
 case'create-team':modal('Novo esquadrão',formTemplate(field('name','Nome da equipa','Ex.: ALCATEIA I'),'team-create','Criar equipa'));break;
 case'remove-team-member':if(confirm('Remover este jogador da equipa?')){await api(`/api/teams/${el.dataset.team}/members/${el.dataset.user}`,'DELETE');flash('Jogador removido da equipa.',true);await refresh();}break;
 case'extend-team':if(confirm('Adicionar 7 dias ao período de adaptação?')){await api(`/api/teams/${el.dataset.team}/extend`,'POST');flash('Período estendido.',true);await refresh();}break;
 case'create-war':modal('Agendar guerra',formTemplate(`${field('title','Nome da guerra','Ex.: Guerra de domingo')}${field('opponent','Guilda adversária','Nome da guilda')}${field('starts_at','Data e hora','', 'datetime-local')}<div><label>Notas táticas (opcional)</label><textarea name="notes" maxlength="1000" placeholder="Informações relevantes"></textarea></div>`,'war-create','Agendar guerra'));break;
 case'war-update':modal('Estado e resultado',formTemplate(`<input type="hidden" name="war_id" value="${eattr(id)}"><div><label>Estado da guerra</label><select name="status"><option value="PLANNED">Agendada</option><option value="LIVE">A decorrer</option><option value="DONE">Terminada</option><option value="CANCELLED">Cancelada</option></select></div>${field('result','Resultado registado manualmente','Ex.: Vitória 3–1','text','',false)}`,'war-update','Guardar resultado'));break;
 case'war-lineup':{const lineup=await api(`/api/wars/${id}/lineup`);let players=[];if(hasAny(operations))players=(await api('/api/members')).members.filter(m=>m.status==='ACTIVE');modal('Escalação de guerra',`<div class="stack">${lineup.lineup.length?lineup.lineup.map(p=>`<div class="line-item"><span class="line-title">${esc(p.username)}</span>${tag(p.confirmed?'Confirmado':'Por confirmar',p.confirmed?'good':'warn')}</div>`).join(''):empty('Sem convocados','Ainda não foram convocados membros para esta guerra.','users')}${lineup.lineup.some(p=>p.user_id===state.me.id&&!p.confirmed)?btn('Confirmar presença','primary','check',`data-action="war-confirm" data-id="${id}"`):''}${hasAny(operations)?formTemplate(`<input type="hidden" name="war_id" value="${id}"><div><label>Convocar membro</label><select name="user_id" required>${optionMembers(players)}</select></div>`,'war-callup','Convocar'):'</div>'}</div>`);break;}
 case'war-confirm':await api(`/api/wars/${id}/confirm`,'POST');closeModal();flash('Presença confirmada!',true);await refresh();break;
 case'add-score':{const people=(await api('/api/members')).members.filter(m=>m.status==='ACTIVE');modal('Ajustar pontuação',formTemplate(`<div><label>Jogador</label><select name="user_id" required>${optionMembers(people)}</select></div>${field('points','Pontos (+ ou −)','Ex.: 150','number')}${field('reason','Justificação obrigatória','Origem / correção dos pontos')}`,'score','Registar pontos'));break;}
 case'award':{const people=(await api('/api/members')).members.filter(m=>m.status==='ACTIVE');modal('Atribuir conquista',formTemplate(`<div><label>Membro homenageado</label><select name="member_id" required>${optionMembers(people)}</select></div>${field('title','Título da conquista','Ex.: Destaque da semana')}<div><label>Descrição</label><textarea name="description" maxlength="400" placeholder="Motivo do reconhecimento"></textarea></div>`,'award','Atribuir medalha'));break;}
 case'create-event':modal('Novo evento',formTemplate(`${field('title','Nome do evento','Ex.: Treino tático')}${field('starts_at','Data e hora','', 'datetime-local')}<div><label>Descrição</label><textarea name="details" maxlength="1000"></textarea></div>`,'event-create','Criar evento'));break;
 case'feed-more':state.feedOffset+=30;await refresh();break;
 case'feed-prev':state.feedOffset=Math.max(0,state.feedOffset-30);await refresh();break;
 case'like-post':await api(`/api/feed/${id}/react`,'POST');await refresh();break;
 case'comments':state.commentsFor=state.commentsFor===id?null:id;await refresh();break;
 case'channel':state.channel=el.dataset.channel;state.target='';await refresh();break;
 case'delete-post':if(confirm('Queres mesmo eliminar esta publicação?')){await api(`/api/feed/${id}`,'DELETE');flash('Publicação ocultada.',true);await refresh();}break;
 case'read-notice':await api(`/api/notifications/${id}/read`,'POST');await refresh();break;
 case'approve-member':if(confirm('Aprovar a candidatura deste jogador?')){await api(`/api/admin/pending/${id}/approve`,'POST');flash('Jogador aprovado!',true);await refresh();}break;
 case'approve-proposal':if(confirm('Confirmas a tua assinatura nesta decisão estratégica?')){const result=await api(`/api/admin/proposals/${id}/approve`,'POST');flash(result.executed?'Decisão executada após as duas assinaturas.':'Primeira aprovação registada.',true);await refresh();}break;
 case'modal-close':closeModal();break;
 case'reload':await refresh();break;
 }}

async function submitForm(form){const mode=form.dataset.form;const d=formObj(form);let message='Operação concluída.';let close=true;let update=true;
 switch(mode){
 case'login':{const r=await api('/api/auth/login','POST',d);state.csrf=r.csrf;state.me=await api('/api/auth/me');close=false;state.page='dashboard';location.hash='dashboard';if(state.me.status!=='ACTIVE')accountScreen();else await showPage();message='Sessão iniciada.';break;}
 case'register':await api('/api/auth/register','POST',d);state.authTab='login';renderAuth();message='Candidatura submetida. Aguarda aprovação.';break;
 case'recover':await api('/api/auth/recover','POST',d);state.authTab='login';renderAuth();message='Se a conta existir, serão enviadas instruções.';break;
 case'reset':{const tok=new URLSearchParams(location.search).get('reset');await api('/api/auth/reset-password','POST',{token:tok,password:d.password});history.replaceState(null,'','/');state.authTab='login';renderAuth();message='Palavra-passe alterada. Entra novamente.';break;}
 case'appeal':await api('/api/admin/appeal','POST',d);form.reset();message='Recurso submetido ao Conselho dos Fundadores.';update=false;break;
 case'team-create':await api('/api/teams','POST',{name:d.name});break;
 case'team-add':await api(`/api/teams/${d.team_id}/members`,'POST',{user_id:d.user_id});message='Jogador colocado na equipa.';break;
 case'team-captain':await api(`/api/teams/${d.team_id}/captain`,'POST',{user_id:d.user_id});message='Capitão designado.';break;
 case'war-create':await api('/api/wars','POST',{title:d.title,opponent:d.opponent,starts_at:new Date(d.starts_at).toISOString(),notes:d.notes||''});message='Guerra agendada.';break;
 case'war-update':await api(`/api/wars/${d.war_id}/status`,'POST',{status:d.status,result:d.result});message='Resultado atualizado.';break;
 case'war-callup':await api(`/api/wars/${d.war_id}/lineup`,'POST',{user_id:d.user_id});message='Convocatória enviada.';break;
 case'score':await api('/api/ranking/entries','POST',{user_id:d.user_id,points:Number(d.points),reason:d.reason});message='Pontuação registada.';break;
 case'event-create':await api('/api/events','POST',{title:d.title,starts_at:new Date(d.starts_at).toISOString(),details:d.details||''});message='Evento registado.';break;
 case'post':{const files=[...(form.querySelector('[name=images]')?.files||[])];const media_ids=await uploadImages(files);await api('/api/feed','POST',{body:d.body,media_ids});state.feedOffset=0;message='Publicação criada.';break;}
 case'comment':await api(`/api/feed/${d.post_id}/comments`,'POST',{body:d.body});message='Comentário publicado.';break;
 case'message':await api('/api/messages','POST',{body:d.body,channel:state.channel,target_id:state.target});message='Mensagem enviada.';break;
 case'award':await api('/api/hall/awards','POST',d);message='Conquista atribuída.';break;
 case'profile':await api('/api/profile','PATCH',{username:d.username,ff_uid:d.ff_uid||'',bio:d.bio||'',privacy_public:Boolean(form.querySelector('[name=privacy_public]').checked)});state.me.username=d.username;message='Perfil atualizado.';break;
 case'password':await api('/api/auth/change-password','POST',d);state.me=null;state.csrf='';renderAuth();message='Palavra-passe alterada. Inicia sessão novamente.';update=false;break;
 case'warning':await api(`/api/admin/members/${d.user_id}/warning`,'POST',{reason:d.reason});message='Advertência registada.';break;
 case'proposal':{const payload={action:d.action,reason:d.reason||'',serious:Boolean(form.querySelector('[name=serious]').checked)};
    if(d.action==='SET_ROLE'){payload.target_user_id=d.target_user_id;payload.role=d.role;}
    else if(d.action==='SUSPEND'){payload.target_user_id=d.target_user_id;payload.days=Number(d.days);}
    else if(d.action==='REINSTATE'){payload.target_user_id=d.target_user_id;}
    else if(d.action==='FINALIZE_WEEK'){payload.week_start=d.week_start;}
    await api('/api/admin/proposals','POST',payload);message='Decisão registada. Aguarda a segunda assinatura.';break;}
 default:throw Error('Formulário não reconhecido.');
 }
 if(close)closeModal();
 if(update&&state.me?.status==='ACTIVE')await refresh();
 flash(message,true);
}

document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();await go(nav.dataset.nav);return;}const target=e.target.closest('[data-action]');if(!target||state.busy)return;e.preventDefault();state.busy=true;try{await actionClick(target);}catch(err){flash(err.message||'Não foi possível completar a operação.');}finally{state.busy=false;}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(state.busy)return;state.busy=true;const button=form.querySelector('[type=submit],button:not([type])');if(button)button.disabled=true;try{await submitForm(form);}catch(err){flash(err.message||'Erro ao guardar.');}finally{state.busy=false;if(button?.isConnected)button.disabled=false;}});
document.addEventListener('input',e=>{if(e.target?.id==='member-filter'){const query=e.target.value.trim().toLocaleLowerCase('pt-PT');const filtered=(state.data.members||[]).filter(u=>u.username.toLocaleLowerCase('pt-PT').includes(query)||(u.ff_uid||'').includes(query));const target=$('#member-list');if(target)target.innerHTML=memberCards(filtered);}});
document.addEventListener('change',async e=>{if(e.target?.id==='channel-target'){state.target=e.target.value;try{await refresh();}catch(err){flash(err.message);}}});
window.addEventListener('online',()=>{flash('Ligação restabelecida.',true);if(state.me?.status==='ACTIVE')refresh();});
window.addEventListener('offline',()=>flash('Sem internet. Algumas funções poderão não responder.'));
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(titles[hash]&&hash!==state.page&&state.me?.status==='ACTIVE')go(hash);});
// Short polling for chat; never invent unread/read receipts or instant WebSocket presence.
setInterval(async()=>{if(!state.me||state.me.status!=='ACTIVE'||state.page!=='messages'||state.busy||document.activeElement?.matches('input,textarea,select'))return;try{await refresh();}catch{}},12000);
setInterval(async()=>{if(!state.me||state.me.status!=='ACTIVE')return;try{const r=await api('/api/notifications');if(r.unread!==state.data.unread){state.data.unread=r.unread;const dot=$('.notification-dot');if(!dot&&r.unread){const bell=$('.top-right [data-nav="notifications"]');bell?.insertAdjacentHTML('beforeend','<i class="notification-dot"></i>');}else if(dot&&!r.unread)dot.remove();}}catch{}},40000);
init();
